import time
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

URLS = [f"https://httpbin.org/delay/1?id={i}" for i in range(20)]

def fetch(url: str) -> tuple[str, int]:
    resp = requests.get(url, timeout=10)
    return url, len(resp.content)

def main() -> None:
    start = time.perf_counter()
    results = []
    # 20 I/O-bound tasks; threads overlap the network waits
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {pool.submit(fetch, url): url for url in URLS}
        for fut in as_completed(futures):
            url = futures[fut]
            try:
                u, size = fut.result(timeout=15)
                results.append((u, size))
            except Exception as exc:
                print(f"{url} failed: {exc}")
    elapsed = time.perf_counter() - start
    print(f"Fetched {len(results)} urls in {elapsed:.1f}s")

if __name__ == "__main__":
    main()
